import av, numpy as np, json
from PIL import Image
f='zip/v118_v3.1_1728x960_15s.mp4'
regs={'national':(670,40,1060,290),'regional':(110,485,300,735),'title':(520,310,1310,520)}
c=av.open(f); frames={}
for i,fr in enumerate(c.decode(video=0)):
    if i>=200: frames[i]=fr.to_ndarray(format='yuv444p16le') if False else fr.reformat(format='yuv444p').to_ndarray()
a=frames
out={}
for i in (300,374):
    im=Image.open(f'frames/f1728_{i:03d}.png')
    for n,b in regs.items():
        cr=im.crop(b); cr.save(f'frames/crop_{n}_{i}_1x.png'); cr.resize((cr.width*2,cr.height*2),Image.NEAREST).save(f'frames/crop_{n}_{i}_2x.png')
# temporal diffs in static end region
for n,(x0,y0,x1,y1) in regs.items():
    d={}
    for i,j in ((300,301),(373,374),(200,374)):
        Y=lambda k:a[k][0,y0:y1,x0:x1].astype(float)
        d[f'Y_mad_{i}_{j}']=float(np.abs(Y(i)-Y(j)).mean())
    out[n]=d
# frame-to-frame global diff to find static range
g=[float(np.abs(a[k][0].astype(float)-a[k-1][0].astype(float)).mean()) for k in range(201,375)]
out['global_mad_201_374_first_last']= [round(g[0],3),round(g[-1],3),round(max(g),3),round(min(g),3)]
out['last_changing_frame']=[k for k,v in zip(range(201,375),g) if v>0.05][-1:] 
# chroma HF energy ratio (Laplacian-ish) in national emblem at frame 374
x0,y0,x1,y1=regs['national']
for pl,nm in enumerate('YUV'):
    p=a[374][pl,y0:y1,x0:x1].astype(float)
    out[f'hf_{nm}_nat']=float(np.abs(np.diff(p,axis=1)).mean())
print(json.dumps(out,indent=1))
E
